/**
 * Board 42 section 1 B-H: Settings › Multiplayer › Create secret, under Relay URL.
 *
 * - Automatic (default): "Generated by Kimo, kept in the keychain"; Show reveals it with Copy for
 *   30 s (or until Settings closes); Regenerate makes a new one.
 * - Custom: a masked input with show and copy (the relay's own value).
 * - No secret needed: a relay that accepts new rooms without one (set by the wizard).
 *
 * Regenerate (and Custom back to Automatic) only changes what Kimo sends, so the relay has to
 * restart with the new value. A relay on this computer or one Kimo deployed with flyctl: a
 * confirm naming who disconnects (F, G), then Kimo restarts or redeploys it and shows progress in
 * this row (H). Any other relay: Banner/Warning "Restart your relay" with Copy secret until a
 * test passes with the new secret (E).
 */
import { Banner, Dialog, DialogScrim } from "@kimo/ui"
import { type Ref, useEffect, useMemo, useState } from "react"
import { createPortal } from "react-dom"
import { Icon } from "../../lib/icons"
import { flySecretSteps } from "../relay-setup/commands"
import { elapsed } from "../relay-setup/local"
import { testRelaySetup } from "../relay-setup/relay-test"
import { runFlySteps } from "../relay-setup/runner"
import { type SecretMode, SecretReveal } from "../relay-setup/secret"
import { type RelaySetupServices, useLocalRelay, useRelaySetupState } from "../relay-setup/services"
import { kimoRestarts } from "../relay-setup/store"
import { AUTO_CUSTOM, SecretBlock, type SecretModeOption, Spacer, Track } from "./relay-parts"
import { useShareToast } from "./shared"
import "./relay-wizard.css"

/** Who a restart disconnects now: names (up to three), then "and n more". */
export interface DisconnectImpact {
  people: readonly string[]
  more: number
}

function namesOf(impact: DisconnectImpact | null): string | null {
  if (!impact || impact.people.length + impact.more === 0) return null
  const names = [...impact.people]
  if (impact.more > 0) return `${names.join(", ")} and ${impact.more} more`
  if (names.length === 1) return names[0] as string
  return `${names.slice(0, -1).join(", ")} and ${names.at(-1)}`
}

/** The confirm's description (F: this computer, G: Fly.io). */
export function regenerateDescription(
  kind: "local" | "fly",
  app: string | null,
  impact: DisconnectImpact | null,
): string {
  const names = namesOf(impact)
  const count = impact ? impact.people.length + impact.more : 0
  if (kind === "local")
    return `Kimo restarts the relay on this computer with it. ${
      names ? `${names} ${count === 1 ? "is" : "are"}` : "Everyone connected is"
    } disconnected now and reconnect${count === 1 ? "s" : ""} on their own in a few seconds.`
  return `Kimo sets the new secret on ${app ?? "your app"} and redeploys it on Fly.io. That takes about a minute; ${
    count > 0 ? `${count} ${count === 1 ? "person is" : "people are"}` : "everyone connected is"
  } disconnected until it is back.`
}

const hostOf = (url: string | null) => {
  if (!url) return null
  try {
    return new URL(url).host
  } catch {
    return url
  }
}

export interface RelaySecretSettingProps {
  services: RelaySetupServices
  relayUrl: string | null
  impact?: DisconnectImpact | null
  customRef?: Ref<HTMLInputElement>
}

export function RelaySecretSetting({
  services,
  relayUrl,
  impact = null,
  customRef,
}: RelaySecretSettingProps) {
  const { store, local, host } = services
  const setup = useRelaySetupState(store)
  const localState = useLocalRelay(local)
  const toast = useShareToast()
  const reveal = useMemo(() => new SecretReveal(services.clock), [services.clock])
  useEffect(() => () => reveal.dispose(), [reveal])
  const [secret, setSecret] = useState<string | null>(null)
  const [custom, setCustom] = useState("")
  const [confirm, setConfirm] = useState<"local" | "fly" | null>(null)
  const [progress, setProgress] = useState<{
    title: string
    startedAt: number
    value: number
  } | null>(null)
  const [madeAt, setMadeAt] = useState<number | null>(null)
  const [now, setNow] = useState(services.clock.now())
  const host_ = hostOf(relayUrl)

  useEffect(() => {
    let live = true
    void (async () => {
      const value =
        setup.secretMode === "auto" ? await store.ensureAutoSecret() : await store.secret()
      if (!live) return
      setSecret(value)
      if (setup.secretMode === "custom") setCustom(value ?? "")
    })()
    return () => {
      live = false
    }
  }, [setup.secretMode, store])

  // The progress row and "made N s ago" tick once a second while shown.
  useEffect(() => {
    if (!progress && madeAt === null) return
    let handle: unknown
    const tick = () => {
      setNow(services.clock.now())
      handle = services.clock.setTimeout(tick, 1000)
    }
    handle = services.clock.setTimeout(tick, 1000)
    return () => services.clock.clearTimeout(handle)
  }, [progress, madeAt, services.clock])

  const copy = async (value: string) => {
    try {
      await services.copy(value)
      toast({ tone: "success", icon: "copy", text: "Secret copied" })
    } catch {
      toast({ tone: "danger", text: "Couldn't copy to the clipboard" })
    }
  }

  const regenerate = async () => {
    const flyctl =
      setup.path === "fly" && host ? !!(await host.findTool("flyctl").catch(() => null)) : false
    const restarts = kimoRestarts(setup, {
      localRunning: localState?.status === "running",
      flyctl,
    })
    if (restarts) {
      setConfirm(restarts)
      return
    }
    const fresh = await store.regenerate()
    await store.update({ restartPending: true })
    setSecret(fresh)
    setMadeAt(services.clock.now())
  }

  const runRestart = async (kind: "local" | "fly") => {
    setConfirm(null)
    const fresh = await store.regenerate()
    setSecret(fresh)
    const startedAt = services.clock.now()
    if (kind === "local" && local) {
      setProgress({ title: "Restarting the relay with the new secret", startedAt, value: 0.3 })
      const state = await local.restart(fresh)
      setProgress(null)
      if (state.status !== "running")
        toast({ tone: "danger", text: `Couldn't restart the relay. ${state.error ?? ""}`.trim() })
      return
    }
    if (kind === "fly" && host && setup.fly) {
      const app = setup.fly.app
      setProgress({ title: "Redeploying on Fly.io with the new secret", startedAt, value: 0 })
      const run = await runFlySteps(
        host,
        flySecretSteps({ app, secret: fresh }),
        app,
        async (url) => (await testRelaySetup(url, fresh, services.test)).outcome === "ok",
        (r) =>
          setProgress({
            title: "Redeploying on Fly.io with the new secret",
            startedAt,
            value: r.lines.filter((l) => l.status === "done").length / r.lines.length,
          }),
        services.clock,
      )
      setProgress(null)
      if (run.error) {
        await store.update({ restartPending: true })
        setMadeAt(services.clock.now())
        toast({ tone: "danger", text: `Couldn't redeploy ${app}: ${run.error}` })
      }
    }
  }

  const onMode = async (mode: SecretMode) => {
    if (mode === setup.secretMode) return
    if (mode === "auto") {
      // Custom back to Automatic works like Regenerate.
      await regenerate()
      return
    }
    reveal.hide()
    if (mode === "custom") {
      setCustom("")
      await store.update({ secretMode: "custom" })
    } else await store.update({ secretMode: mode })
  }

  const modes: readonly SecretModeOption[] =
    setup.secretMode === "none"
      ? [
          { value: "custom", label: "Custom" },
          { value: "none", label: "No secret needed" },
        ]
      : AUTO_CUSTOM

  const autoDesc =
    madeAt !== null
      ? `New secret made ${Math.max(0, Math.round((now - madeAt) / 1000))} s ago.`
      : host_
        ? `Sent to ${host_} when you create a room.`
        : "Sent to your relay when you create a room."

  return (
    <div className="mp-setting" data-pen="O29Rk8">
      <SecretBlock
        variant="settings"
        store={store.secrets.backend}
        mode={setup.secretMode}
        modes={modes}
        onMode={(m) => void onMode(m)}
        secret={secret}
        autoDesc={autoDesc}
        reveal={reveal}
        onCopy={(v) => void copy(v)}
        onRegenerate={() => void regenerate()}
        custom={custom}
        onCustom={setCustom}
        onCustomBlur={() => void store.setCustomSecret(custom)}
        customHelp={`Your own value, for a relay you configured yourself. ${
          store.secrets.backend === "browser" ? "Kept in this browser." : "Kept in the keychain."
        }`}
        {...(customRef ? { customRef } : {})}
        {...(progress
          ? {
              progress: (
                <div className="rw-progress-box" data-box="redeploying" role="status">
                  <div className="rw-check" data-status="running">
                    <span className="rw-check__icon rw-spin" aria-hidden="true">
                      <Icon name="loader-circle" size={14} />
                    </span>
                    <span className="rw-label-strong">{progress.title}</span>
                    <Spacer />
                    <span className="rw-mono">{elapsed(now - progress.startedAt)}</span>
                  </div>
                  <Track value={progress.value} />
                </div>
              ),
            }
          : {})}
      />
      {setup.restartPending && setup.secretMode === "auto" && secret && !progress && (
        <Banner
          tone="warning"
          className="rw-banner"
          icon={<Icon name="triangle-alert" size={16} />}
          title="Restart your relay"
          body={`${host_ ?? "Your relay"} still has the old secret. Redeploy it with the new one.`}
          actions={[
            {
              id: "copy",
              label: "Copy secret",
              variant: "primary",
              icon: <Icon name="copy" size={14} />,
            },
          ]}
          onAction={() => void copy(secret)}
        />
      )}
      {confirm &&
        createPortal(
          <DialogScrim>
            <Dialog
              className="rw-regenerate-dialog"
              icon={<Icon name="refresh-cw" size={16} />}
              title={confirm === "local" ? "Make a new secret?" : "Make a new secret and redeploy?"}
              description={regenerateDescription(confirm, setup.fly?.app ?? null, impact)}
              footnote={
                confirm === "local"
                  ? "Old secret stops working at once."
                  : "Uses your flyctl login."
              }
              confirmLabel={confirm === "local" ? "Make new secret" : "Redeploy"}
              onCancel={() => setConfirm(null)}
              onConfirm={() => void runRestart(confirm)}
            />
          </DialogScrim>,
          document.body,
        )}
    </div>
  )
}

/**
 * After a relay test passes in Settings: whether the relay takes the secret Kimo sends. Clears
 * the restart banner when it does; "rejected" when it does not.
 */
export async function confirmSecret(
  services: RelaySetupServices,
  url: string,
): Promise<"accepted" | "rejected" | "unknown"> {
  const secret = await services.store.sendSecret()
  const r = await testRelaySetup(url, secret, services.test)
  if (r.outcome === "ok") {
    if (services.store.getState().restartPending)
      await services.store.update({ restartPending: false })
    return "accepted"
  }
  return r.outcome === "secret-rejected" ? "rejected" : "unknown"
}
